        assertSame(baseOptions, result);
        assertTrue(baseOptions.hasOption("a"));
        assertTrue(baseOptions.hasOption("b"));
    }

    @Test
    public void testAddOptionsWithDuplicateKey() {
        baseOptions.addOption("a", "first-a", false, "first description");
        optionsToAdd.addOption("a", "second-a", false, "second description");

        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            baseOptions.addOptions(optionsToAdd);
        });

        assertTrue(exception.getMessage().contains("Duplicate key: a"));
    }

    @Test
    public void testAddOptionsWithOptionGroups() {
        OptionGroup groupToAdd = new OptionGroup();
        groupToAdd.addOption(Option.builder("d").build());
        groupToAdd.addOption(Option.builder("e").build());
        optionsToAdd.addOptionGroup(groupToAdd);

        Options result = baseOptions.addOptions(optionsToAdd);

        assertSame(baseOptions, result);
        // Since Options doesn't expose getOptionGroups(), we verify the options within the group are present
        assertTrue(baseOptions.hasOption("d"));
        assertTrue(baseOptions.hasOption("e"));
    }

    @Test
    public void testAddOptionsWithEmptyCollection() {
        Options emptyOptions = new Options();

        Options result = baseOptions.addOptions(emptyOptions);

        assertSame(baseOptions, result);
        assertFalse(baseOptions.hasOption("x"));
    }

    @Test
    public void testAddOptionsMergesOptionsAndGroups() {
        OptionGroup groupToAdd = new OptionGroup();
        groupToAdd.addOption(Option.builder("f").build());
        optionsToAdd.addOptionGroup(groupToAdd);
        optionsToAdd.addOption("g", "generate", false, "generate output");

        Options result = baseOptions.addOptions(optionsToAdd);

        assertSame(baseOptions, result);
        assertTrue(baseOptions.hasOption("f"));
        assertTrue(baseOptions.hasOption("g"));
    }

    @Test
    public void testAddOptionsPartialDuplicate() {
        baseOptions.addOption("x", "x-opt", false, "desc");
        optionsToAdd.addOption("x", "x-dup", false, "desc"); // Duplicate
        optionsToAdd.addOption("y", "y-opt", false, "desc"); // Valid

