    }

    @Test
    public void testAddOptionGroupRequired() {
        OptionGroup group = new OptionGroup();
        group.addOption(Option.builder("a").build());
        group.addOption(Option.builder("b").build());
        group.setRequired(true);

        Options returnedOptions = options.addOptionGroup(group);

        assertSame(options, returnedOptions, "addOptionGroup should return the same Options instance");

        assertTrue(options.getRequiredOptions().contains(group), "The group should be in the required options collection");

        assertTrue(options.hasOption("a"), "Option 'a' should be added to Options");
        assertTrue(options.hasOption("b"), "Option 'b' should be added to Options");

        // Verify that individual options in a required group are not marked as required themselves
        assertFalse(options.getOption("a").isRequired(), "Option 'a' should not be required individually");
        assertFalse(options.getOption("b").isRequired(), "Option 'b' should not be required individually");

        // Verify the group mapping
        assertEquals(group, options.getOptionGroup(options.getOption("a")), "Option 'a' should map to the group");
        assertEquals(group, options.getOptionGroup(options.getOption("b")), "Option 'b' should map to the group");
    }

    @Test
    public void testAddOptionGroupNotRequired() {
        OptionGroup group = new OptionGroup();
        group.addOption(Option.builder("x").build());
        group.setRequired(false);

        options.addOptionGroup(group);

        assertFalse(options.getRequiredOptions().contains(group), "The group should not be in the required options collection");

        assertTrue(options.hasOption("x"), "Option 'x' should be added to Options");
        assertFalse(options.getOption("x").isRequired(), "Option 'x' should not be required");
        assertEquals(group, options.getOptionGroup(options.getOption("x")), "Option 'x' should map to the group");
    }

