    @Test
    public void testBreakCharFoundNearLimit() {
        final CharSequence text = "abcdefghijklmno pqr";
        // Width 10. Range 0-9. No break.
        // Search backward for whitespace from limit-1.
        // Expected behavior: find whitespace or chop.
        // Logic: if break found in loop, return it. 
        // This test ensures the first loop (forward scan for BREAK_CHAR_SET) works.
        final CharSequence text2 = "abcde fghijk";
        assertEquals(5, TextHelpAppendable.indexOfWrap(text2, 10, 0));
    }

    @Test
    public void testWhitespaceFoundBeforeLimit() {
        // "abcdef ghij" -> length 10. Width 6. startPos 0.
        // Forward scan 0 to 5 (a-f): No BREAK_CHAR_SET (assuming only specific chars are breaks).
        // Backward scan from 5: 'f' (not ws), 'e'... 'a' (not ws).
        // Wait, "abcdef ghij" has space at 6. 6 is outside limit (0+6).
        // Forward scan range: [0, 6). Indices 0,1,2,3,4,5.
        // If no break char found:
        // limit = min(6, 10) = 6.
        // Backward scan from limit-1 (5) down to 0. No whitespace.
        // Return limit - 1 = 5.

        // Let's test case where whitespace IS found backward.
        final CharSequence text = "abc def";
        // Width 10. startPos 0.
