        // Returns 0 (since pos > startPos -> 0 > 0 is false). 
        // Code: `return pos > startPos ? pos : limit - 1;`
        // If pos == startPos (0), return limit - 1 (2).

        final CharSequence text = " abc";
        // Logic check:
        // limit = 3. pos=3..0. Finds ws at 0.
        // pos (0) is not > startPos (0).
        // Returns limit - 1 = 2. (Chops " ab" -> " abc" effectively taking full chunk).
        assertEquals(2, TextHelpAppendable.indexOfWrap(text, 5, 0));
    }

